+interface TextNode {
+  type: "text";
+  value: string;
+}
+
+interface InterpolationNode {
+  type: "interpolation";
+  path: string;
+  escaped: boolean;
+  position: Position;
+}
+
+interface BlockNode {
+  type: "block";
+  kind: "if" | "each";
+  path: string;
+  body: Node[];
+  alternate: Node[] | null;
+  position: Position;
+}
+
+interface Frame {
+  node: BlockNode;
+  branch: Node[];
+}
+
+interface Context {
+  root: unknown;
+  value: unknown;
+  index?: number;
+}
+
+function error(message: string, position: Position): Error {
+  return new Error(`${message} at line ${position.line}, column ${position.column}`);
+}
+
+function positionAt(template: string, offset: number): Position {
+  const before = template.slice(0, offset);
+  const line = before.split("\n").length;
+  const lastNewline = before.lastIndexOf("\n");
+  return { line, column: offset - lastNewline };
+}
+
+function parse(template: string): Node[] {
+  const root: Node[] = [];
+  const stack: Frame[] = [];
+  let target = root;
+  let cursor = 0;
+
+  const appendText = (value: string) => {
+    if (value) target.push({ type: "text", value });
+  };
+
+  while (cursor < template.length) {
+    const start = template.indexOf("{{", cursor);
+    if (start === -1) {
+      appendText(template.slice(cursor));
+      break;
+    }
+
+    appendText(template.slice(cursor, start));
+    const triple = template.startsWith("{{{", start);
+    const close = triple ? "}}}" : "}}";
+    const contentStart = start + (triple ? 3 : 2);
+    const end = template.indexOf(close, contentStart);
+    const position = positionAt(template, start);
+    if (end === -1) throw error("Unclosed tag", position);
+
+    const content = template.slice(contentStart, end).trim();
+    cursor = end + close.length;
+
+    if (!content || content.startsWith("!")) continue;
+    if (triple) {
+      target.push({ type: "interpolation", path: content, escaped: false, position });
+      continue;
+    }
+    if (content === "else") {
+      const frame = stack.at(-1);
+      if (!frame) throw error("Else outside a block", position);
+      if (frame.node.alternate) throw error("Duplicate else", position);
+      frame.node.alternate = [];
+      frame.branch = frame.node.alternate;
+      target = frame.branch;
+      continue;
+    }
+    if (content.startsWith("#")) {
+      const [kind, ...pathParts] = content.slice(1).trim().split(/\s+/);
+      const path = pathParts.join(" ");
+      if ((kind !== "if" && kind !== "each") || !path) {
+        throw error(`Unknown block '${content.slice(1).trim()}'`, position);
+      }
+      const node: BlockNode = { type: "block", kind, path, body: [], alternate: null, position };
+      target.push(node);
+      stack.push({ node, branch: node.body });
+      target = node.body;
+      continue;
+    }
+    if (content.startsWith("/")) {
+      const kind = content.slice(1).trim();
+      const frame = stack.at(-1);
+      if (!frame) throw error(`Unexpected closing block '${kind}'`, position);
+      if (kind !== frame.node.kind) {
+        throw error(`Mismatched closing block '${kind}', expected '${frame.node.kind}'`, position);
+      }
+      stack.pop();
+      target = stack.at(-1)?.branch ?? root;
+      continue;
+    }
+    target.push({ type: "interpolation", path: content, escaped: true, position });
+  }
+
+  const unclosed = stack.at(-1);
+  if (unclosed) throw error(`Unclosed block '${unclosed.node.kind}'`, unclosed.node.position);
+  return root;
+}
+
+function resolve(path: string, context: Context): unknown {
+  if (path === "this") return context.value;
+  if (path === "@index") return context.index;
+  if (!path || !/^[A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*$/.test(path)) {
+    throw new Error(`Invalid path '${path}'`);
+  }
+
+  let value: unknown = context.root;
+  for (const part of path.split(".")) {
+    if (value === null || value === undefined) return undefined;
+    if (typeof value !== "object" && typeof value !== "function") return undefined;
+    value = (value as Record<string, unknown>)[part];
+  }
+  return value;
+}
+
+function isTruthy(value: unknown): boolean {
+  if (value === null || value === undefined || value === false || value === 0 || value === "") return false;
+  return !Array.isArray(value) || value.length > 0;
+}
+
+function scalar(value: unknown, position: Position): string {
+  if (value === null || value === undefined) return "";
+  if (typeof value === "object" || typeof value === "function" || typeof value === "symbol") {
+    throw error("Cannot render a non-scalar value", position);
+  }
+  return String(value);
+}
+
+function escapeHtml(value: string): string {
+  return value.replace(/[&<>"']/g, (character) => ({
+    "&": "&amp;",
+    "<": "&lt;",
+    ">": "&gt;",
+    '"': "&quot;",
+    "'": "&#39;",
+  })[character]!);
+}
+
+function renderNodes(nodes: Node[], context: Context): string {
+  let output = "";
+  for (const node of nodes) {
+    if (node.type === "text") output += node.value;
+    else if (node.type === "interpolation") {
+      const value = scalar(resolve(node.path, context), node.position);
+      output += node.escaped ? escapeHtml(value) : value;
+    } else {
+      const value = resolve(node.path, context);
+      if (node.kind === "if") {
+        output += renderNodes(isTruthy(value) ? node.body : (node.alternate ?? []), context);
+      } else if (Array.isArray(value) && value.length > 0) {
