+import { expect, test } from "bun:test";
+import { render } from "../src/engine.ts";
+
+test("interpolates and escapes values", () => {
+  expect(render("Hello {{user.name}}!", { user: { name: "A&B" } })).toBe("Hello A&amp;B!");
+  expect(render("{{value}} {{{value}}}", { value: '<a "x">' })).toBe("&lt;a &quot;x&quot;&gt; <a \"x\">");
+});
+
+test("preserves whitespace and omits comments", () => {
+  expect(render(" a {{! invisible }}\n b ", {})).toBe(" a \n b ");
+});
+
+test("renders nested conditionals with template truthiness", () => {
+  expect(render("{{#if enabled}}yes{{#if name}} {{name}}{{else}}!{{/if}}{{else}}no{{/if}}", { enabled: true, name: "Ada" })).toBe("yes Ada");
+  expect(render("{{#if items}}yes{{else}}no{{/if}}", { items: [] })).toBe("no");
+});
+
