+  expect(render("{{#each values}}{{this}}{{else}}none{{/each}}", { values: [] })).toBe("none");
+});
+
+test("handles missing values and rejects non-scalars", () => {
+  expect(render("{{missing.value}}", {})).toBe("");
+  expect(() => render("{{value}}", { value: {} })).toThrow("Cannot render a non-scalar value");
+});
+
+test("reports structural errors with positions", () => {
+  expect(() => render("x\n{{/if}}", {})).toThrow("line 2, column 1");
+  expect(() => render("{{#if ok}}{{else}}{{else}}{{/if}}", { ok: true })).toThrow("Duplicate else");
+  expect(() => render("{{#each list}}", { list: [] })).toThrow("Unclosed block 'each'");
+  expect(() => render("{{#wat value}}{{/wat}}", {})).toThrow("Unknown block");
+});
*** Add File: README.md
+# Mini Template
+
+A dependency-free TypeScript template renderer for Bun.
+
+## Use as a library
+
+```ts
+import { render } from "./src/engine.ts";
+
+render("Hello, {{user.name}}!", { user: { name: "Ada" } });
+```
+
+`{{path}}` escapes HTML; `{{{path}}}` does not. Supported blocks are `{{#if path}}...{{else}}...{{/if}}` and `{{#each path}}...{{else}}...{{/each}}`. Loops expose `{{this}}` and `{{@index}}`; ordinary paths continue to resolve from the root data object. Comments use `{{! comment }}`.
+
+## CLI
+
+```sh
+bun run src/cli.ts TEMPLATE_FILE DATA.json
+```
+
+The command writes rendered output to stdout. Errors are sent to stderr with a non-zero exit code.
+
+## Test
+
+```sh
+bun test
+```
